      if (mode == "sendNow") {
        info.headerMessageId = headerMessageId;
      }
      resolve(info);
    },
    async onFailure({ exception }) {
      afterSaveSendEventTracker.removeListener(listener);
      reject(exception);
    },
    modes: [sendMode],
    extension,
  };
  afterSaveSendEventTracker.addListener(listener);
});

